def _lang() -> str:
    lang = current_lang.get()
    return lang if lang in LANGS else "en"


def norm_lang(code: str | None) -> str:
    """Map a user language / Telegram language_code to a supported language (default en)."""
    short = (code or "").lower().split("-")[0]
    return short if short in LANGS else "en"


def t(key: str, **kwargs) -> str:
    text = COPY[key][LANGS.index(_lang())]
    return text.format(**kwargs) if kwargs else text


def weekdays() -> list[str]:
    return t("weekdays").split(",")


def group_label(group: str) -> str:
    """Localized muscle group label; unknown groups come back unchanged."""
    return t(f"m_{group}") if f"m_{group}" in COPY else group
